CREATE TABLE bundles(id uuid PRIMARY KEY, project_id text NOT NULL, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(project_id,id));
CREATE TABLE versions(id uuid PRIMARY KEY, project_id text NOT NULL, bundle_id uuid NOT NULL, parent_version_id uuid NULL, digest text NOT NULL, payload bytea NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(project_id,bundle_id,id), FOREIGN KEY(project_id,bundle_id) REFERENCES bundles(project_id,id), FOREIGN KEY(project_id,bundle_id,parent_version_id) REFERENCES versions(project_id,bundle_id,id));
CREATE TABLE channels(project_id text NOT NULL, bundle_id uuid NOT NULL, name text NOT NULL, revision bigint NOT NULL, version_id uuid NOT NULL, PRIMARY KEY(project_id,bundle_id,name), FOREIGN KEY(project_id,bundle_id,version_id) REFERENCES versions(project_id,bundle_id,id));
CREATE TABLE comparisons(id uuid PRIMARY KEY, project_id text NOT NULL, bundle_id uuid NOT NULL, body jsonb NOT NULL, complete boolean NOT NULL, submitter text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(project_id,bundle_id,id), FOREIGN KEY(project_id,bundle_id) REFERENCES bundles(project_id,id));
CREATE TABLE proposals(id uuid PRIMARY KEY, project_id text NOT NULL, bundle_id uuid NOT NULL, parent_version_id uuid NOT NULL, request jsonb NOT NULL, status text NOT NULL, attempts int NOT NULL DEFAULT 0, candidate_version_id uuid NULL, rationale text NULL, error text NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(project_id,bundle_id,id), FOREIGN KEY(project_id,bundle_id) REFERENCES bundles(project_id,id));
CREATE TABLE promotions(id uuid PRIMARY KEY, project_id text NOT NULL, bundle_id uuid NOT NULL, channel text NOT NULL, revision bigint NOT NULL, version_id uuid NOT NULL, previous_version_id uuid NULL, comparison_id uuid NULL, unevaluated_reason text NULL, reviewer text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE idempotency(principal_id text NOT NULL, project_id text NOT NULL, method text NOT NULL, path text NOT NULL, key text NOT NULL, fingerprint bytea NOT NULL, response_status int NOT NULL, response_body bytea NOT NULL, expires_at timestamptz NOT NULL, PRIMARY KEY(principal_id,project_id,method,path,key));
CREATE INDEX proposals_jobs ON proposals(status,created_at);
